// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        blockNum = bound(blockNum, 1, type(uint64).max);

        vm.roll(blockNum);
        vm.warp(blockNum);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "call failed");

        if (block.number % 15 == 0) {
            assertTrue(address(c).balance == 0, "payout block must drain balance");
        } else {
            assertTrue(address(c).balance == 20 ether, "non-payout block must keep balance");
        }
    }
}
